CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027054529_AjustarProductosParaInventario') THEN
    CREATE TABLE "Productos" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" character varying(150) NOT NULL,
        "Sku" character varying(50) NOT NULL,
        "Categoria" character varying(100),
        "PrecioVenta" numeric(12,2) NOT NULL,
        "CostoCompra" numeric(12,2) NOT NULL,
        "Stock" integer NOT NULL,
        "StockMinimo" integer NOT NULL DEFAULT 5,
        CONSTRAINT "PK_Productos" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Productos_PrecioVenta_MayorOIgualCosto" CHECK ("PrecioVenta" >= "CostoCompra"),
        CONSTRAINT "CK_Productos_Stock_NoNegativo" CHECK ("Stock" >= 0),
        CONSTRAINT "CK_Productos_StockMinimo_NoNegativo" CHECK ("StockMinimo" >= 0)
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027054529_AjustarProductosParaInventario') THEN
    CREATE UNIQUE INDEX "IX_Productos_Sku" ON "Productos" ("Sku");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261027054529_AjustarProductosParaInventario') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20261027054529_AjustarProductosParaInventario', '10.0.14');
    END IF;
END $EF$;
COMMIT;

